<?php require 'config.php';$u=require_login();require_innovations();page_start('Project lab',$u);heading('SMALL BUILDS. BIG POSSIBILITIES.','Made by your community.','Share a working link or describe your idea. Give specific, constructive feedback.');$id=filter_var($_GET['project']??0,FILTER_VALIDATE_INT)?:0; ?>
<?php if($id):$project=one('SELECT p.*,u.name,u.photo,u.photo FROM projects p JOIN users u ON u.id=p.user_id WHERE p.id=? AND u.active=1',[$id]);if(!$project){http_response_code(404);echo '<section class="card"><h2>Project not available.</h2><a href="showcase.php">Back to project lab</a></section>';page_end();exit;}?>
<a href="showcase.php">← All projects</a><article class="card project-hero"><span class="badge">Built by <?=e($project['name'])?></span><h2><?=e($project['title'])?></h2><div class="body-text"><?=e($project['description'])?></div><?php if($project['url']):?><p><a class="button secondary" href="<?=e($project['url'])?>" target="_blank" rel="noopener noreferrer">Visit project ↗</a></p><small>External community link; review it before opening.</small><?php endif;?>
<?php if($project['user_id']==$u['id']||$u['role']==='admin'):?><form method="post" action="innovate.php" data-confirm="Remove this project and all its feedback?"><?php innovation_hidden('project_delete',$id);?><button class="ghost danger">Remove project</button></form><?php endif;?></article>
<section class="card"><h2>Constructive feedback</h2><?php $feedback=rows('SELECT f.*,u.name,u.photo FROM project_feedback f JOIN users u ON u.id=f.user_id WHERE f.project_id=? ORDER BY f.id',[$id]);foreach($feedback as $f):?><div class="reply"><strong><?=e($f['name'])?></strong><div class="body-text"><?=e($f['body'])?></div><?php if($u['role']==='admin'):?><form method="post" action="innovate.php" data-confirm="Remove this feedback?"><?php innovation_hidden('feedback_delete',(int)$f['id']);?><button class="ghost danger">Remove feedback</button></form><?php endif;?></div><?php endforeach;if(!$feedback)echo '<p>Be the first to share a helpful observation.</p>';?><form method="post" action="innovate.php"><?php innovation_hidden('feedback',$id);textarea('Your feedback','body');?><button class="button">Post feedback</button></form></section>
<?php else:?>
<details><summary>+ Share something you built</summary><form class="card" method="post" action="innovate.php"><?php innovation_hidden('project');input('Project title','title');textarea('What you built and what you learned','description');input('Project URL (optional)','url','url','',false);?><button class="button">Publish my project</button></form></details>
<div class="grid"><?php $projects=rows('SELECT p.*,u.name,u.photo,(SELECT COUNT(*) FROM project_feedback f WHERE f.project_id=p.id) feedback FROM projects p JOIN users u ON u.id=p.user_id WHERE u.active=1 ORDER BY p.id DESC LIMIT 60');foreach($projects as $p):?><article class="card"><span class="badge"><?=e($p['name'])?></span><h2><?=e($p['title'])?></h2><p><?=e(mb_substr($p['description'],0,220))?></p><a href="showcase.php?project=<?=$p['id']?>">Explore project · <?=$p['feedback']?> feedback →</a></article><?php endforeach;if(!$projects):?><section class="card empty-state"><h2>Your first project belongs here.</h2><p>No projects have been published yet. Use the form above to share one—no polished portfolio required.</p></section><?php endif;?></div>
<?php endif;page_end(); ?>